<?php
/** Integrated Blog administration: editorial table, typed-block editor, taxonomy/byline library, moderation, history and canonical settings form. */
declare(strict_types=1);
use DBLESSCMS\{BlogModel,BlogStore,BlogRouter,BlogView,Plugins,PluginOptions,Security,Icons,HttpError};
use function DBLESSCMS\{e,asset};
/** Resolve a plugin-owned admin label; takes key, returns literal text for contextual escaping without side effects. */
$t=static fn(string $key): string=>$context->language->text('blog.'.$key);
/** Resolve a local private route; takes route/query, returns URL without writing state. */
$url=static fn(string $route,array $query=[]): string=>BlogRouter::url($context,$route,$query);
$repository=new BlogStore($context->store);$snapshot=$repository->read();$data=$snapshot['data'];$revision=$snapshot['revision'];$csrf=Security::token();$route=$context->route;
$registry=new Plugins($context->store);$enabled=$registry->state('blog')['enabled'];
/** Render shared mutation fields safely; takes revision/extra text fields, writes escaped hidden inputs and returns nothing. */
$hidden=static function(string $revision,array $extra=[]) use($csrf): void {
  foreach (['csrf_token'=>$csrf,'revision'=>$revision]+$extra as $name=>$value) echo '<input type="hidden" name="'.e($name).'" value="'.e($value).'">';
};
/** Render an icon-only POST action; takes operation/id/label/icon/extra/revision, writes a safe small form and raises unknown icon errors. */
$action=static function(string $operation,string $id,string $label,string $icon,array $extra=[],?string $version=null) use($context,$hidden,$revision): void {
  echo '<form method="post" action="'.e($context->url($operation)).'" data-blog-form'.(in_array($operation,['trash','taxonomy-remove'],true)?' data-confirm="'.e($context->language->text('blog.confirm'.($operation==='trash'?'Delete':'Remove'))).'"':'').'>';
  $hidden($version??$revision,['id'=>$id]+$extra);echo '<button class="icon-button" type="submit" title="'.e($label).'" aria-label="'.e($label).'">'.Icons::svg($icon,$context->base).'</button></form>';
};
?>
